float phi = (1.+sqrt(5.))/2.;
vec3 campos = vec3(0,0,-2);
float focal = 1.;
mat3 matrot(vec3 xyz) {
    mat3 rx = mat3(vec3(1,0,0),vec3(0,-sin(xyz.x),cos(xyz.x)),vec3(0,cos(xyz.x),sin(xyz.x)));
    mat3 ry = mat3(vec3(cos(xyz.y),0,sin(xyz.y)),vec3(0,1,0),vec3(-sin(xyz.y),0,cos(xyz.y)));
    mat3 rz = mat3(vec3(cos(xyz.z),sin(xyz.z),0),vec3(-sin(xyz.z),cos(xyz.z),0),vec3(0,0,1));
    return rx * ry * rz;
        }
float dPoint(vec2 pos, vec3 point) {
    return ceil(point.z-length(pos-point.xy));
        }
float dLine(vec2 pos, vec2 a, vec2 b) {
    float d = 0.;
    vec2 di = a-b;
    float x = 0.;
    for (float i = 0.; i<length(di)*100.;i++) {
        d = dPoint(pos,vec3(b+i*di/(length(di)*100.),0.01));
        x = max(x,d);
            }
    return x;
                }
float dTri(vec2 pos, vec2 a, vec2 b, vec2 c) {
    float x = 0.;
    float d = 0.;
    vec2 ab = a-b;
    vec2 cb = c-b;
    for (float i = 0.; i < 50.; i++) {
        d = dLine(pos,b+ab*i/50.,b+cb*i/50.);
        x = max(x,d);
        if (x > 0.) break;
            }
    return x;
                }
vec2 Project(vec3 point) {
    vec3 rel = point-campos;
    rel *= focal/distance(campos,rel);
    rel.z = 0.;
    return rel.xy;
        }
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates
    vec2 uv = (fragCoord-0.5*iResolution.xy)/iResolution.y;
    vec3 col = vec3(0);
    vec3 rot = vec3(iTime,sin(iTime),1.57);
    vec3 va = vec3(0,phi,1);
    vec2 proja = Project(matrot(rot)*va);
    float a = dPoint(uv, vec3(Project(matrot(rot)*va),0.01));
    vec3 vb = vec3(0,phi,-1);
    vec2 projb = Project(matrot(rot)*vb);
    float b = dPoint(uv, vec3(Project(matrot(rot)*vb),0.01));
    vec3 vc = vec3(0,-phi,1);
    vec2 projc = Project(matrot(rot)*vc);
    float c = dPoint(uv, vec3(Project(matrot(rot)*vc),0.01));
    vec3 vd = vec3(0,-phi,-1);
    vec2 projd = Project(matrot(rot)*vd);
    float d = dPoint(uv, vec3(Project(matrot(rot)*vd),0.01));
    vec3 ve = vec3(-1,0,phi);
    vec2 proje = Project(matrot(rot)*ve);
    float e = dPoint(uv, vec3(Project(matrot(rot)*ve),0.01));
    vec3 vf = vec3(-1,0,-phi);
    vec2 projf = Project(matrot(rot)*vf);
    float f = dPoint(uv, vec3(Project(matrot(rot)*vf),0.01));
    vec3 vg = vec3(1,0,phi);
    vec2 projg = Project(matrot(rot)*vg);
    float g = dPoint(uv, vec3(Project(matrot(rot)*vg),0.01));
    vec3 vh = vec3(1,0,-phi);
    vec2 projh = Project(matrot(rot)*vh);
    float h = dPoint(uv, vec3(Project(matrot(rot)*vh),0.01));
    vec3 vi = vec3(phi,1,0);
    vec2 proji = Project(matrot(rot)*vi);
    float i = dPoint(uv, vec3(Project(matrot(rot)*vi),0.01));
    vec3 vj = vec3(phi,-1,0);
    vec2 projj = Project(matrot(rot)*vj);
    float j = dPoint(uv, vec3(Project(matrot(rot)*vj),0.01));
    vec3 vk = vec3(-phi,1,0);
    vec2 projk = Project(matrot(rot)*vk);
    float k = dPoint(uv, vec3(Project(matrot(rot)*vk),0.01));
    vec3 vl = vec3(-phi,-1,0);
    vec2 projl = Project(matrot(rot)*vl);
    float l = dPoint(uv, vec3(Project(matrot(rot)*vl),0.01));
    float la = dLine(uv,proja,projg);
    float lb = dLine(uv,proja,proje);
    float lc = dLine(uv,proja,projk);
    float ld = dLine(uv,proja,projb);
    float le = dLine(uv,proja,proji);
    float lf = dLine(uv,projg,proji);
    float lg = dLine(uv,projb,proji);
    float lh = dLine(uv,projg,proje);
    float li = dLine(uv,proje,projk);
    float lj = dLine(uv,projk,projb);
    float lk = dLine(uv,projd,projl);
    float ll = dLine(uv,projd,projj);
    float lm = dLine(uv,projd,projc);
    float ln = dLine(uv,projd,projf);
    float lo = dLine(uv,projd,projh);
    float lp = dLine(uv,projc,projj);
    float lq = dLine(uv,projj,projh);
    float lr = dLine(uv,projh,projf);
    float ls = dLine(uv,projf,projl);
    float lt = dLine(uv,projl,projc);
    float lu = dLine(uv,projc,proje);
    float lv = dLine(uv,proje,projl);
    float lw = dLine(uv,projl,projk);
    float lx = dLine(uv,projk,projf);
    float ly = dLine(uv,projf,projb);
    float lz = dLine(uv,projb,projh);
    float laa = dLine(uv,projh,proji);
    float lab = dLine(uv,proji,projj);
    float lac = dLine(uv,projj,projg);
    float lad = dLine(uv,projg,projc);
    float total = la+lb+lc+ld+le+lf+lg+lh+li+lj+lk+ll+lm+ln+lo+lp+lq+lr+ls+lt+lu+lv+lw+lx+ly+lz+laa+lab+lac+lad;
    float face = dTri(uv,proja,projb,proji);
    // Output to screen
    fragColor = vec4(face,total,total,1.0);
}
